VALUES ('hire_1788809413642_860381', 'e93a2f49-3cc2-4f48-be9f-63f53dedae96', 'tcs', 'Associate Cloud & Cyber Defense Engineer', 'Full-time', 'Cloud & Cybersecurity', 'Bengaluru, India (Hybrid)', 'Hybrid', 5, '2026-11-30T00:00:00.000Z'::timestamptz, 'published', 'Join our frontline defense team analyzing cloud telemetry, container security, and SIEM detections.', ARRAY['Triage real-time intrusion alarms from SIEM and EDR platforms.', 'Design automated mitigation scripts using Python and Bash.', 'Perform vulnerability assessments on staging cloud infrastructure.']::text[], ARRAY['Cybersecurity', 'Cloud Computing', 'Python', 'Linux']::text[], ARRAY['Docker', 'Kubernetes', 'SIEM', 'Terraform']::text[], ARRAY['Bachelor''s degree in Computer Science, Information Security, or STEM field.', 'Minimum 65% aggregate or 6.8 CGPA.']::text[], ARRAY['Security certification or active CTF competition participation.']::text[], ARRAY['student_id']::text[], '{"enabled":true,"testTitle":"Cloud & Cyber Defense Benchmark Exam","timeLimitMinutes":30,"totalMarks":25,"passingPercentage":60,"difficultyDistribution":{"beginner":1,"intermediate":1,"advanced":0},"selectedQuestionIds":["ind_q_1788809412817_20f8ee","ind_q_1788809413167_64b514"],"testPaper":[{"id":"ind_q_1788809413167_64b514","questionText":"What is the primary role of an API Gateway in cloud microservices?","questionType":"mcq","difficulty":"beginner","domainId":"cloud-engineering","conceptTag":"api-gateway","marks":2,"options":[{"id":"opt_gw_1","label":"A","text":"Direct hardware RAID controller redundancy"},{"id":"opt_gw_2","label":"B","text":"Request routing, rate limiting, and centralized authentication"},{"id":"opt_gw_3","label":"C","text":"Client-side GPU shader rendering acceleration"},{"id":"opt_gw_4","label":"D","text":"Local browser cookie session persistence"}],"correctOptionId":"opt_gw_2","explanation":"API Gateways sit between clients and microservices to manage traffic routing, throttling, and auth verification."},{"id":"ind_q_1788809412817_20f8ee","questionText":"Which cryptographic algorithm provides asymmetric public-key encryption?","questionType":"mcq","difficulty":"intermediate","domainId":"cybersecurity","conceptTag":"public-key-crypto","marks":3,"options":[{"id":"opt_rsa","label":"A","text":"RSA (Rivest-Shamir-Adleman)"},{"id":"opt_aes","label":"B","text":"AES-256 (Advanced Encryption Standard)"},{"id":"opt_des","label":"C","text":"Triple DES"},{"id":"opt_rc4","label":"D","text":"RC4 Stream Cipher"}],"correctOptionId":"opt_rsa","explanation":"RSA is an asymmetric cipher utilizing mathematically linked public and private key pairs."}],"approvalStatus":"approved","aiReviewStatus":"reviewed","aiReviewFeedback":{"relevanceScore":50,"difficultyConsistency":"1 Beginner, 1 Intermediate, 0 Advanced","duplicateWarnings":[],"skillsCoverage":[],"suggestions":["Consider adding questions covering: cybersecurity, cloud computing, python, linux."],"isPassed":true},"approvedAt":"2026-09-07T19:30:16.876Z","publishedAt":"2026-09-07T19:30:17.109Z"}'::jsonb, '{"mode":"Virtual","type":"Technical & Behavioral","estimatedRounds":2,"instructions":"Shortlisted candidates will receive round meeting invitations."}'::jsonb, '2026-09-07T19:30:13.642Z'::timestamptz, '2026-09-07T19:30:17.350Z'::timestamptz, '2026-09-07T19:30:17.350Z'::timestamptz)
